package com.pp.shaderlod.sildurprefix;import com.google.gson.*;import java.util.*;import java.security.MessageDigest;public final class SildurPrefixProfile{private SildurPrefixProfile(){}private static Map<String,String> load(String path,String sha){try(var in=SildurPrefixProfile.class.getResourceAsStream("/assets/shaderlod/adapters/qualification/"+path)){if(in==null)return Map.of();byte[] b=in.readAllBytes();if(!HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b)).equals(sha))return Map.of();var m=new TreeMap<String,String>();for(var e:JsonParser.parseString(new String(b,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().entrySet())m.put(e.getKey(),e.getValue().getAsString());return Map.copyOf(m);}catch(Exception e){return Map.of();}}private static final Map<String,String> EXPECTED=load("sildur-prefix-options.json","e3691ecfad4c78c37d04d736d5f8623531aa6be4e4dc850b998a98006a53ff09");private static final Map<String,String> FUNCTIONS=load("sildur-prefix-functions.json","bb1fe845ae886edb4e63943d0c879f942a2cb4ca6023a1a8d7f2440f7699191f");public static boolean accepts(Map<String,String> actual){if(actual==null||EXPECTED.size()!=128||(actual.size()!=128&&actual.size()!=131))return false;var normalized=new TreeMap<>(actual);for(String key:List.of("SHADERLOD_SILDUR_PIXEL_GRAPH","SHADERLOD_SILDUR_SPATIAL_REUSE","SHADERLOD_SILDUR_LIGHTING_RATE")){if(normalized.containsKey(key)&&!"0".equals(normalized.remove(key)))return false;}return EXPECTED.equals(normalized);}public static Map<String,String> functions(){return FUNCTIONS;}public static Map<String,String> expected(){return EXPECTED;}}